const message = $json;
const headers = message.payload?.headers || [];
const header = name => headers.find(h => String(h.name).toLowerCase() === name.toLowerCase())?.value || '';
function decode(data) {
  if (!data) return '';
  return Buffer.from(String(data).replace(/-/g,'+').replace(/_/g,'/'), 'base64').toString('utf8');
}
function bodies(part, out = []) {
  if (!part) return out;
  if (part.mimeType === 'text/plain' && part.body?.data) out.push(decode(part.body.data));
  for (const child of (part.parts || [])) bodies(child, out);
  return out;
}
let body = bodies(message.payload).join('\n').trim();
if (!body) body = decode(message.payload?.body?.data).trim();
const from = header('From');
const emailMatch = from.match(/<([^>]+)>/) || from.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
const sender = emailMatch ? (emailMatch[1] || emailMatch[0]) : '';
if (!message.id || !sender || !body) throw new Error('Gmail message is missing id, sender, or plain-text body');
return [{json:{
  mailbox_id:$env.SCOPELEDGER_MAILBOX_ID || 'gmail-primary',
  message_id:message.id,
  thread_id:message.threadId || '',
  sender_email:sender.toLowerCase(),
  subject:header('Subject'),
  request_body:body.slice(0,12000)
}}];
